/* eslint-disable react/prop-types */
import React, { useMemo, useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Button,
  TableRow,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  Box,
  MenuItem,
  Popover,
} from '@mui/material';
import PersonAddAltIcon from '@mui/icons-material/PersonAddAlt';
import Snackbar from '@mui/material/Snackbar';
import Alert from '@mui/material/Alert';
import AlertTitle from '@mui/material/AlertTitle';
import { axios } from '../../utils/axios';
import { replaceStarsInEmailAddress, replaceStarsInMobileNumber } from '../../utils/sensitive'
import { updateUrlParams } from '../../utils/urlUtilis';

// components
import Label from '../../components/label';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import CustomTable from '../../components/customTable/CustomTable';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

// const EnhancedTableRow = CustomTable((props) => <TableRow {...props} />)
const EnhancedTableRow = CustomTable(TableRow);

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const { settingsData, i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const navigate = useNavigate();
  const [opens, setOpens] = useState(false);
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [userList, setUserList] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [verify, setVerify] = useState({
    open: false,
    vertical: 'top',
    horizontal: 'center',
  });
  const [anchorEl, setAnchorEl] = useState(null)
  const [menuRowId, setMenuRowId] = useState(null);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);


  const handleActionMenu = (event, id) => {
    setAnchorEl(event.currentTarget)
    setMenuRowId(id);
  }

  const handleActionMenuClose = () => {
    setAnchorEl(null);
    setMenuRowId(null);
  }

  const TABLE_HEAD = [
    { id: 'name', label: i18?.ACCOUNTSTITLE?.FULL_NAME || "Full Name", alignRight: false },
    { id: 'email', label: i18?.ACCOUNTSTITLE?.EMAIL_ID || "Email ID", alignRight: false },
    { id: 'phone', label: i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone NUmber", alignRight: false },
    { id: 'currentBalance', label: i18?.ACCOUNTSTITLE?.WALLET_BALANCE || "Wallet Balance", alignRight: false },
    { id: 'payments', label: i18?.ACCOUNTSTITLE?.PAYMENTS || "Payments", alignRight: false },
    { id: 'verified', label: i18?.ACCOUNTSTITLE?.VERIFIED || "Verified", alignRight: false },
    { id: 'isActive', label: i18?.ACCOUNTSTITLE?.STATUS || "Status", alignRight: false },
    { id: 'action', label: i18?.ACCOUNTSTITLE?.ACTION || "Action", alignRight: false },
  ];

  const { vertical, horizontal, open } = verify;

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/auth/users?_page=${page}&_limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
          if (value) url += `&${key}=${value}`;
      });
      const res = await axios.get(url);
      if (res.status === 200) {
        setUserList(res.data.data.userList);
        setTotalCount(res.data.data.totalCount ? res.data.data.totalCount : 0);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleformdata = async (ids) => {
    try {
      const res = await axios.get(`module/auth/user/${ids}`);
      if (res.status === 200) {
        navigate(`/dashboard/edituser?userId=${ids}`, {
          state: { datas: res.data.data.userDetail, editId: ids, types: res.data.data.userDetail.type },
        });
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const deleteModal = (ids) => {
    sessionStorage.setItem('userId', ids);
    setOpens(true);
  };

  const deleteUser = async () => {
    const ids = sessionStorage.getItem('userId');
    try {
      const res = await axios.delete(`module/auth/user/${ids}`);
      if (res.status === 200) {
        setOpens(false);
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
      } else {
        setOpens(false);
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      setOpens(false);
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = userList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'User';
    navigate('/dashboard/addprofile', { state: { types: type } });
  };

  const createwallet = (ids, fullname, email, currentbal) => {
    const type = 'User';
    navigate('/dashboard/wallet', { state: { ids, fullname, email, types: type, currentbal } });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(1);
    setFilterName(event.target.value);
  };

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const handleformdata = async (ids) => {
      console.log(ids);

      try {
        const res = await axios.get(`module/auth/user/${ids}`);
        if (res.status === 200) {
          navigate(`/dashboard/edituser?userId=${ids}`, {
            state: { datas: res.data.data.userDetail, editId: ids, types: res.data.data.userDetail.type },
          });
        } else {
          GenerateToastConfig(res.data.message);
        }
      } catch (err) {
        GenerateToastConfig(err?.response?.data?.message);
      }
    };

    const deleteModal = (ids) => {
      sessionStorage.setItem('userId', ids);
      setOpens(true);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => handleformdata(value)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    )
  }

  const columns = [
    {
      header: i18?.ACCOUNTSTITLE?.FULL_NAME || "Full Name",
      accessorKey: "fullname",
      showFilter: true, 
      id: "firstname",
      // Cell: ({ cell: { value } }) => <span>{value}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.EMAIL_ID || "Email ID",
      accessorKey: "email",
      id: "email",
      showFilter: true, 
      // Cell: ({ cell: { value } }) => <span>{replaceStarsInEmailAddress(value, settingsData, value)}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number",
      accessorKey: "phone",
      id: "phone",
      showFilter: true, 
      // Cell: ({ cell: { value } }) => <span>{replaceStarsInMobileNumber(value, settingsData, value)}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.WALLET_BALANCE || "Wallet Balance",
      accessorKey: "currentBalance",
      id: "currentBalance",
      cell: ({ row }) => <span>{row?.original?.currentBalance || "---"}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.PAYMENTS || "Payments",
      accessorKey: "payments",
      id: "payments",
      cell: ({ row }) => (
        <Label
          sx={{
            cursor: "pointer",
            width: '37px',
            height: '37px',
            background: '#FFE5E6',
            color: '#FF5A60',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={() => createwallet(
            row.original._id,
            row.original.fullname,
            row.original.email,
            row.original.currentBalance,
          )}
        >
          <Iconify icon={"mdi:wallet"} />
        </Label>
      ),
    },
    {
      header: i18?.ACCOUNTSTITLE?.VERIFIED || "Verified",
      accessorKey: "verified",
      id: "verified",
      cell: ({ cell }) => {
        const value = cell?.getValue();
        return (
          <Label
            sx={{
              width: '37px',
              height: '37px',
              background: value ? '#E6FFFA' : '#FEF5E5',
              color: value ? '#0DAC6F' : '#FA886B',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
            }}
          >
            <Iconify icon={value ? "mdi:account-check" : "mdi:account-remove"} />
          </Label>
        );
      },
    },
    {
      header: i18?.ACCOUNTSTITLE?.STATUS || "Status",
      accessorKey: "isActive",
      id: "isActive",
      showFilter: false,
      cell: ({ cell }) => {
        const value = cell?.getValue();
        return (
          <Label
            sx={{
              width: value ? '56px' : '66px',
              height: value ? '25px' : '27px',
              borderRadius: '60px',
              background: value ? '#E6FFFA' : '#FEF5E5',
              color: value ? '#0DAC6F' : '#FA886B',
            }}
          >
            {value ? 'Active' : 'Inactive'}
          </Label>
        );
      }
    },
    {
      header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
      accessorKey: "_id",
      id: "action",
      cell: ActionComponent
    }
  ];

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> User | Admin panel </title>
      </Helmet>

      {isMobile && <Stack direction="row" alignItems="center" style={{ marginBottom: '30px' }} justifyContent="space-between">
        <Box>
          <Typography variant="h4" gutterBottom>
            {i18?.ACCOUNTSTITLE?.USER_LIST || "User List"}
          </Typography>
        </Box>
        <Button
          variant="contained"
          sx={{
            padding: "9px 28px",
            background: "#FF5A60",
            '&:hover': {
              background: "#FF4A50"
            }
          }}
          onClick={handleOpenModal}
          startIcon={<PersonAddAltIcon />}
        >
          {i18?.ACCOUNTSTITLE?.ADD_USER || "Add User"}
        </Button>
      </Stack>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          {/* <Box
            sx={{
              width: '37px',
              height: '37px',
              background: '#FF5A60',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
              cursor: 'pointer'
            }}
          >
            <Iconify icon={"mdi:arrow-left"} width={24} height={24} color="white" />
          </Box> */}
          <Typography variant="h4" gutterBottom sx={{ marginLeft: '10px', marginTop: "10px" }}>
            {i18?.ACCOUNTSTITLE?.USER_LIST || 'User List'}
          </Typography>
        </Box>
        <Stack direction="row" alignItems="center">
          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            search={search}
            setsearch={setsearch}
            onFilterName={handleFilterByName}
          />
          <Button sx={{
            padding: "9px 28px"
          }}
            variant="contained"
            onClick={handleOpenModal}
            startIcon={<PersonAddAltIcon />}>
            {i18?.ACCOUNTSTITLE?.ADD_USER || "Add User"}
          </Button>
        </Stack>
      </Stack>}

      <Card sx={{ padding: '0px 0px', margin: '0px 0px' }}>
        {isMobile && <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          search={search}
          setsearch={setsearch}
          onFilterName={handleFilterByName}
        />}

        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={userList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>
      </Card>
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />

      {/* <TanstackTable data={data} columns={columns} /> */}


      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={deleteUser}
      />

      <Snackbar
        anchorOrigin={{ vertical, horizontal }}
        autoHideDuration={3000}
        open={open}
        onClose={() => setVerify({ ...verify, open: false })}
        key={vertical + horizontal}
      >
        <Alert onClose={() => setVerify({ ...verify, open: false })} severity="success" sx={{ width: '100%' }}>
          <AlertTitle>Verified</AlertTitle>
        </Alert>
      </Snackbar>
    </>
  );
}